function commission_types():array{return ['staff_contract119'=>'عمولة مبيعات عقود الموظفين','supervisor_contract119'=>'عمولة عقود مشرف','sales_agent'=>'مبيعات مسئول','sales_referral'=>'إحالة عميل','sales_check'=>'التشييك وإتمام الأوردر','sales_full'=>'أوردر كامل','sales_delivery'=>'نصيب التوصيل من المبيعات','collection'=>'عمولة التحصيل','delivery_contract'=>'عمولة العقود'];}
function commission_calculate(array $rule,float $base):float {
 if(!is_finite($base)||$base<0)fail('أساس العمولة غير صالح.');$mode=$rule['mode'];$rate=(float)$rule['rate'];$limit=(float)($rule['threshold']??0);$upper=(float)($rule['upper_rate']??0);
 if($mode!=='percent'&&floor($base)!==$base)fail('عدد العقود عدد صحيح.');
 $value=match($mode){'percent'=>$base*$rate/100,'unit'=>$base*$rate,'retro'=>$base*($base>$limit?$upper:$rate),'progressive'=>min($base,$limit)*$rate+max(0,$base-$limit)*$upper,default=>throw new RuntimeException('طريقة عمولة غير صالحة.')};return round($value,3);
}
function commission_rule(int $uid,string $type,string $date):?array {
 $found=[];foreach(query("SELECT * FROM ep_records WHERE module='commission_rule' AND status='approved' AND (user_id=? OR user_id=0) AND date_from<=? AND (date_to IS NULL OR date_to>=?) ORDER BY date_from DESC,id DESC",[$uid,$date,$date])->fetchAll()as $r){$v=decode($r['body_json']);if(($v['type']??'')===$type)$found[]=$r;}
 foreach($found as $r)if((int)$r['user_id']===$uid)return $r;return $found[0]??null;
}
function commission_month_items(int $uid,string $month):array {return query("SELECT * FROM ep_records WHERE module='commission_month' AND user_id=? AND date_from=? AND status='approved' ORDER BY id",[$uid,$month.'-01'])->fetchAll();}
